#!/usr/bin/env python3
"""Turn 35 Wave 95: THE PENALTY TECHNIQUES, AND TWO MORE TIER 1 DATA POINTS.

Wave 95's centrepieces:

1. THE AIM-LEFT-THEN-SWITCH-RIGHT PENALTY, reported by a player who went from missing every
   penalty to scoring 8/10: aim left, hold for a second, switch right, tap A. It is the clearest
   description yet of how the aim control actually behaves - the aim is set by where you finish,
   not where you start - and it is DLS26-dated (March 2026), which matters because the corpus's
   penalty rules were mostly written against DLS24.

2. THE SEQUENCE-BREAKING PENALTY, which is a genuinely different idea: go middle four or five
   times in a row, then change side once. The keeper's read is pattern-based, so the pattern
   itself is the lever. One player reports not missing a penalty for four months after adopting
   it. That is the only penalty advice in the corpus that is about the opponent's memory rather
   than about your own input.

3. TWO MORE TIER 1 DATA POINTS, which together frame the mission. A skilled player reached Tier 1
   in three weeks on a new account with an average non-maxed team - so the 16-day world record is
   not the only path, and three weeks is the realistic skilled target. And the world-record
   holder's discipline is now on record: **not once did he sell a player** - every signing came
   along for the journey as a starter or a reserve. That is the clearest statement yet that the
   50% resale rule makes selling a loss, not a strategy.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w95')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_pn=new_ev("r/DreamLeagueSoccer 1s5aqel 'Why is scoring penalties just impossible' (27 Mar 2026 - the aim-left-then-switch-right technique, taking the writer from missing every penalty to 8/10), r/DreamLeagueSoccer 1f1sexb (26 Aug 2024 - the sequence-breaking tactic: go middle four or five straight games then change side once), r/DreamLeagueSoccer 1jmtcwh 'Penalty Shootouts' (29 Mar 2025 - the DLL and shootout conversion rates, the down-the-middle penalty, and the low-C and medium-A alternatives), r/DreamLeagueSoccer 1hg5ari 'Set Pieces + Passing Accuracy (+ Penalty) Tips' (17 Dec 2024 - the middle-A penalty against AI), r/DreamLeagueSoccer 1ap2595 (12 Feb 2024 - the ET-season penalty technique with the 1/3-from-the-keeper aim and half-to-two-thirds power, and the claim that headers are the easiest way to score against p2w players), LevelWinner DLS2024 beginner guide (15 Mar 2024 - the SHO-dependent penalty aiming and the 40% A-kick power load), r/DreamLeagueSoccer 14ustvs 'Penalty tips' (the moderate-power near-middle shot and the C-to-the-corner option), r/DreamLeagueSoccer 1qu9lt3 (2 Feb 2026 - Tier 1 in three weeks on an average non-maxed team), r/DreamLeagueSoccer 1qz14ir (8 Feb 2026 - the world-record run and the no-selling discipline), r/DreamLeagueSoccer 1phcvdv (8 Dec 2025 - a DLS25 Tier 1 champion now bouncing between T2 and T1), eslamgaming.com 'Honest Review of Dream League Soccer 2026' (27 Apr 2026 - FLAGGED source claiming player morale and youth potential, both documented negatives)",
    "THE PENALTY TECHNIQUES AND TWO MORE TIER 1 DATA POINTS. (1) THE AIM-LEFT-THEN-SWITCH-RIGHT PENALTY, DLS26-dated: 'for sometime scoring penalties was impossible for me, no exaggerating I missed every single one until I tried this: **I would aim the to the left and hold for a second then I switch to the right and tap A.** I don't know what it is guys I'm scoring 8/10 penalties now.' So the aim is set by where you FINISH, not where you start - which explains the corpus's 'hold the joystick while shooting' rule from the other side. (2) THE SEQUENCE-BREAKING PENALTY, a genuinely different idea: 'just **go middle for 4-5 straight games and then change side once in the sequence** then the penalty is less likely to get saved by the GK. It works for me every time and last time I didn't score a penalty was like 4 months ago before I started following this.' The keeper's read is pattern-based, so the pattern is the lever. **This is the only penalty advice in the corpus that is about the opponent's memory rather than your own input.** (3) THE DOWN-THE-MIDDLE PENALTY: 'Im DLS live always **Hit first right down middle. Works 10/10 times.**' A second voice: 'For penalties against the AI, **go for the middle with a slightly powered A shot** (just enough power for the ball to reach the GK's head)' - because the AI keeper dives. (4) THE CONVERSION BENCHMARK, corroborated a third time: '**Penalties in DLL are not that hard, I score 85-90% of penalties in DLL and 70-80% in shootouts** with A most times, B sometimes.' (5) THE SHO-DEPENDENT AIMING: 'Aim for the **outer foot of the imaginary goalkeeper at the side you're shooting at**. **If your penalty kicker is someone with a low SHO, aim to the body of the imaginary goalie; if it's a natural shooter, you can add a bit more variance to the side** and shoot for the outer leg. **The ideal power load for an A-kick is around 40% for maximum trajectory.**' So the taker's shooting stat changes the target, not just the outcome. (6) THE ET-SEASON PENALTY TECHNIQUE - which matters directly because the corpus's camping rule warns that DLL seasons alternate between draw-allowed and extra-time-mandatory: '**In ET seasons you can score or win in penalties (take penalties by aiming 1/3 distance away from the goalkeeper towards the post the way you want to shoot and holding the pass button to half-2/3 power).**' So in an ET season the shootout is a live scoring route, and it has its own recipe. (7) HEADERS BEAT P2W: 'Place the arrow on your corners slightly inside the default direction and hold C to 2/3-3/4 power and **50% of the time its a free goal. Headers are one of the easiest ways to score against p2w players on dream league live.**' A direct answer to the corpus's maxed-squad-handicap concern: if the handicap is real, the corner header is the reported way through it. (8) TWO MORE TIER 1 DATA POINTS: '**I got to tier 1 after 3 weeks on a new account you just need some skills, with an average non maxed team**' - so three weeks is the realistic skilled target and the 16-day record is not the only path. And the record holder's discipline: '**Not once did I sell any of my players - they all come along for the journey whether as a starting player or a reserve player.**' That is the clearest statement yet that the 50% resale rule makes selling a loss rather than a strategy. (9) A DLS25 TIER 1 CHAMPION STRUGGLING IN DLS26: 'I went from **winning Tier 1 for fun on DLS 25 to now being on the border between T2 and T1, going up then relegated back down repeatedly.**' So the DLS26 defending changes are felt at the top of the ladder, which is a reason to weight the corpus's new defensive rules heavily. (10) A FLAGGED SOURCE CONTRADICTING DOCUMENTED NEGATIVES: eslamgaming's 'honest review' claims 'player morale is tracked' and that you must 'decide whether to sign veterans... or invest in younger prospects with higher potential' - both of which the corpus carries as DOCUMENTED NEGATIVES (no morale, no growth or potential curves). A sixth concrete reason for the existing flag.",
    "THE AIM-LEFT-THEN-SWITCH-RIGHT PENALTY: aim is set by where you FINISH, not where you start - taking one player from missing every penalty to 8/10, DLS26-dated. THE SEQUENCE-BREAKING PENALTY: go middle four or five times then change side once, because the keeper's read is pattern-based - the only penalty advice in the corpus about the opponent's memory rather than your own input. THE DOWN-THE-MIDDLE PENALTY works 10/10 in DLL because the keeper dives. THE SHO-DEPENDENT AIMING: a low-SHO taker aims at the keeper's body, a natural shooter at the outer leg, with a 40% A-kick power load. THE ET-SEASON PENALTY: aim 1/3 from the keeper toward the post, half-to-two-thirds power - which matters because the corpus warns that DLL seasons alternate between draw-allowed and extra-time-mandatory. HEADERS BEAT P2W at 50% conversion. TIER 1 IN THREE WEEKS on an average non-maxed team, and the record holder NEVER SOLD A PLAYER.",
    "THE PENALTY TECHNIQUES AND TWO MORE TIER 1 DATA POINTS",
    quality="community")

add_claim("THE AIM-LEFT-THEN-SWITCH-RIGHT PENALTY, DLS26-dated (March 2026): 'for sometime scoring penalties was impossible for me, no exaggerating I missed every single one until I tried this: **I would aim the to the left and hold for a second then I switch to the right and tap A.** I don't know what it is guys I'm scoring 8/10 penalties now.' **So the aim is set by where you FINISH, not where you start** - which explains the corpus's hold-the-joystick-while-shooting rule from the other side.", 3, "setpieces/aim-left-then-switch-right-penalty", [e_pn], notes="DLS26-dated; the corpus's penalty rules were mostly written against DLS24")
add_claim("THE SEQUENCE-BREAKING PENALTY, a genuinely different idea: 'just **go middle for 4-5 straight games and then change side once in the sequence** then the penalty is less likely to get saved by the GK. It works for me every time and last time I didn't score a penalty was like 4 months ago before I started following this.' **The keeper's read is pattern-based, so the pattern is the lever - and this is the only penalty advice in the corpus that is about the opponent's memory rather than your own input.**", 3, "setpieces/sequence-breaking-penalty", [e_pn])
add_claim("THE DOWN-THE-MIDDLE PENALTY: 'Im DLS live always **Hit first right down middle. Works 10/10 times.**' A second voice: 'For penalties against the AI, **go for the middle with a slightly powered A shot** (just enough power for the ball to reach the GK's head)' - because the AI keeper dives. So the middle is not the safe choice the corpus assumed; against a diving keeper it is the scoring choice.", 3, "setpieces/down-the-middle-penalty", [e_pn])
add_claim("THE CONVERSION BENCHMARK, corroborated a third time: '**Penalties in DLL are not that hard, I score 85-90% of penalties in DLL and 70-80% in shootouts** with A most times, B sometimes.' So a penalty is a high-percentage scoring route, and the shootout is where it drops - which is the opposite of the intuition that shootouts are easier.", 3, "setpieces/penalty-conversion-third-source", [e_pn])
add_claim("THE SHO-DEPENDENT PENALTY AIMING: 'Aim for the **outer foot of the imaginary goalkeeper at the side you're shooting at**. **If your penalty kicker is someone with a low SHO, aim to the body of the imaginary goalie; if it's a natural shooter, you can add a bit more variance to the side** and shoot for the outer leg. **The ideal power load for an A-kick is around 40% for maximum trajectory.**' So the taker's shooting stat changes the TARGET, not just the outcome.", 3, "setpieces/sho-dependent-penalty-aiming", [e_pn])
add_claim("THE ET-SEASON PENALTY TECHNIQUE - which matters directly because the corpus's camping rule warns that DLL seasons alternate between draw-allowed and extra-time-mandatory: '**In ET seasons you can score or win in penalties (take penalties by aiming 1/3 distance away from the goalkeeper towards the post the way you want to shoot and holding the pass button to half-2/3 power).**' So in an ET season the shootout is a live scoring route with its own recipe.", 3, "setpieces/et-season-penalty-technique", [e_pn], notes="Links the season-format warning to a concrete technique")
add_claim("HEADERS BEAT P2W: 'Place the arrow on your corners slightly inside the default direction and hold C to 2/3-3/4 power and **50% of the time its a free goal. Headers are one of the easiest ways to score against p2w players on dream league live.**' **A direct answer to the corpus's maxed-squad-handicap concern: if the handicap is real, the corner header is the reported way through it.**", 3, "setpieces/headers-beat-p2w", [e_pn])
add_claim("A SECOND TIER 1 TIMELINE: '**I got to tier 1 after 3 weeks on a new account you just need some skills, with an average non maxed team**' - so three weeks is the realistic skilled target, the 16-day world record is not the only path, and an average non-maxed squad is sufficient.", 3, "dll/tier-1-in-three-weeks", [e_pn])
add_claim("THE RECORD HOLDER'S DISCIPLINE, and the clearest statement yet that the 50% resale rule makes selling a loss rather than a strategy: '**Not once did I sell any of my players - they all come along for the journey whether as a starting player or a reserve player.**' So the reserve system exists to keep players, not to cycle them.", 3, "dll/never-sold-a-player", [e_pn], notes="Operational consequence of the 50% resale rule")
add_claim("A DLS25 TIER 1 CHAMPION STRUGGLING IN DLS26: 'I went from **winning Tier 1 for fun on DLS 25 to now being on the border between T2 and T1, going up then relegated back down repeatedly.**' So the DLS26 defending changes are felt at the top of the ladder - a reason to weight the corpus's new defensive rules (double-tap clear, shepherd outwards, cancel the chase-downs) heavily.", 3, "dll/dls25-champion-struggling-in-dls26", [e_pn])
add_claim("A FLAGGED SOURCE CONTRADICTING DOCUMENTED NEGATIVES - a sixth concrete reason for the existing flag: eslamgaming's 'honest review' claims '**player morale is tracked**' and that you must 'decide whether to sign veterans who can win games immediately or **invest in younger prospects with higher potential**'. The corpus carries BOTH as documented negatives: no morale system, and no player growth or potential curves.", 4, "errata/eslamgaming-contradicts-documented-negatives", [e_pn], notes="Sixth reason for the eslamgaming flag")

for p in ['EV-508_penalty_techniques.html','EV-508b_tier1_data_points.html']:
    with open(os.path.join(RAW_DIR,p),'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f'Added {cl_id-1-last_cl} claims (CLAIM-{last_cl+1:04d}..CLAIM-{cl_id-1:04d}) and 1 EV (EV-{last_ev+1:03d}). Totals: {n_cl} claims / {n_ev} EVs')
